CREATE OR ALTER TRIGGER [dbo].[OrganizationType_AfterUpdate]
   ON  [dbo].[OrganizationType] 
   AFTER UPDATE
AS 
BEGIN
	SET NOCOUNT ON
	update	T
	set		T.Name = S.Name,
			T.Description = S.Description,
			T.DisplayFormat = S.DisplayFormat,
			T.UpdatedBy = S.UpdatedBy,
			T.UpdatedOn = S.UpdatedOn
	from	AssetType T
			inner join inserted S on T.Object = 'OrganizationType' and T.ObjectID = S.ID
	where s.[State] <> 3;

	DECLARE @ObjectID INT;
	DECLARE @ResourceID INT;

	DECLARE cursorDelete CURSOR
	LOCAL STATIC
	FOR
	SELECT ID AS ObjectID, ISNULL(UpdatedBy, 0) as RecsourceID
	FROM INSERTED
	WHERE [State] = 3;

	OPEN cursorDelete;

	FETCH NEXT FROM cursorDelete INTO @ObjectID, @ResourceID;
	WHILE @@FETCH_STATUS = 0
	BEGIN
		EXEC [dbo].[DeleteObject] 'OrganizationType', @ObjectID, @ResourceID;
		FETCH NEXT FROM cursorDelete INTO @ObjectID, @ResourceID;
	END;
	CLOSE cursorDelete; 
	DEALLOCATE cursorDelete;	
END
